import re

VALID_TYPES = {'feat', 'fix', 'docs', 'style', 'refactor', 'test', 'chore'}

def validate_commit_message(msg: str) -> tuple[bool, str]:
    if not msg or not msg.strip():
        return (False, 'Пустое сообщение')
    header = msg.splitlines()[0].strip()
    if len(header) > 72:
        return (False, 'Превышен лимит 72 символа')
