def git_bisect_find(
    commits: list[str],
    test_fn: callable
) -> str:
    left = 0
    right = len(commits) - 1
    while left + 1 < right:
        mid = (left + right) // 2
        if test_fn(commits[mid]):
            left = mid
        else:
            right = mid
    return commits[right]

