def detect_merge_conflicts(
    base: dict[str, str],
    ours: dict[str, str],
    theirs: dict[str, str]
) -> list[str]:
    conflicts = []
    all_files = (
        set(base) | set(ours) | set(theirs)
    )
    for f in all_files:
        b_val = base.get(f)
        o_val = ours.get(f)
        t_val = theirs.get(f)
        if (
            o_val != b_val
            and t_val != b_val
            and o_val != t_val
        ):
            conflicts.append(f)
    return sorted(conflicts)

